/* ---------- Données ---------- */
let products = [];
let customCatalog = [];
let sales = [];
let lots = [];
let debts = [];
let historyClearedAt = 0;
let expenses = [];
let stats = { todayDate: '', todaySales: 0, todayProfit: 0, totalProfit: 0, totalExpenses: 0 };
let sellingProductId = null;
// Fournisseurs & achats — voir suppliers.js. Fonctionnalité VIP, désactivée par défaut :
// suppliersFeatureEnabled est le réglage (par boutique) qui affiche ou masque tout ça.
let suppliers = [];
let purchases = [];
let suppliersFeatureEnabled = false;

function saveLots(){
  localSet('mombongo:lots', JSON.stringify(lots));
  pushToCloud();
}
// saveDebts() vit maintenant dans debts-sync.js (dettes dans leur propre collection
// Firestore, protégée par rôle — voir firestore.rules).
// saveExpenses() vit maintenant dans expenses-sync.js (dépenses dans leur propre
// collection Firestore, protégée par rôle — voir firestore.rules).
// saveSuppliers() vit maintenant dans suppliers-sync.js, savePurchases() dans
// purchases-sync.js (fournisseurs et achats dans leurs propres collections
// Firestore, protégées par rôle — voir firestore.rules).
function saveSuppliersFeatureEnabled(){
  localSet('mombongo:suppliersFeatureEnabled', JSON.stringify(suppliersFeatureEnabled));
  pushToCloud();
}

function recalcLotQuantities(lotId){
  const lot = lots.find(l=>l.id===lotId);
  if(!lot) return;
  products.filter(p=>p.lotId===lotId).forEach(p=>{
    p.qty = Math.max(0, Math.floor(lot.remainingFraction * p.yieldPerSac + 1e-9));
  });
}

const EXPIRY_WARNING_DAYS = 10;
function daysUntilExpiry(expiryDate){
  // Différence en jours calendaires entre aujourd'hui et la date de péremption (peut être négative si déjà expiré)
  const today = new Date(); today.setHours(0,0,0,0);
  const exp = new Date(expiryDate + 'T00:00:00');
  return Math.round((exp.getTime() - today.getTime()) / 86400000);
}
function expiryLabel(t, days){
  if(days < 0) return t.expiredAlert;
  if(days === 0) return t.expiresToday;
  if(days === 1) return t.expiresTomorrow;
  return t.expiresInDays.replace('{n}', days);
}

const DEBT_DUE_WARNING_DAYS = 3;
const daysUntilDue = daysUntilExpiry; // même calcul de jours, appliqué à une date d'échéance de dette
function dueDateLabel(t, days){
  if(days < 0) return t.dueCountdownOverdue;
  if(days === 0) return t.dueCountdownToday;
  if(days === 1) return t.dueCountdownTomorrow;
  return t.dueCountdownInDays.replace('{n}', days);
}

const HISTORY_RETENTION_MONTHS = 13;
function getHistoryRetentionCutoff(){
  const now = new Date();
  const cutoff = new Date(now.getFullYear(), now.getMonth() - HISTORY_RETENTION_MONTHS, now.getDate());
  return cutoff.getTime();
}
async function archiveOldData(){
  const cutoff = getHistoryRetentionCutoff();
  const oldSalesCount = sales.filter(s => s.date < cutoff).length;
  const oldExpensesCount = expenses.filter(e => e.date < cutoff).length;
  // Une dette/un achat n'est archivé QUE s'il est déjà réglé — de l'argent encore dû ne
  // doit jamais disparaître silencieusement, même si la dette/l'achat est ancien(ne).
  // On se base sur createdAt (dette) / date (achat), qui ne bougent plus une fois le
  // statut passé à "réglé".
  const oldDebtsCount = debts.filter(d => d.status === 'réglé' && (d.createdAt||0) < cutoff).length;
  const oldPurchasesCount = purchases.filter(p => p.status === 'réglé' && (p.date||0) < cutoff).length;
  // Le journal d'activité n'a pas de statut "en cours" à protéger — purge inconditionnelle.
  const oldActivityCount = (activityLog||[]).filter(a => a.date < cutoff).length;
  if(oldSalesCount === 0 && oldExpensesCount === 0 && oldDebtsCount === 0 && oldPurchasesCount === 0 && oldActivityCount === 0) return;
  // Les compteurs de bénéfices/dépenses (stats) sont indépendants de ces listes détaillées :
  // les supprimer ici ne change donc rien aux totaux déjà affichés, seule la mémoire est libérée.
  sales = sales.filter(s => s.date >= cutoff);
  expenses = expenses.filter(e => e.date >= cutoff);
  debts = debts.filter(d => !(d.status === 'réglé' && (d.createdAt||0) < cutoff));
  purchases = purchases.filter(p => !(p.status === 'réglé' && (p.date||0) < cutoff));
  activityLog = (activityLog||[]).filter(a => a.date >= cutoff);
  await saveSales();
  saveExpenses();
  saveDebts();
  savePurchases();
  if(typeof saveActivityLog === 'function') saveActivityLog();
}

async function loadData(){
  if(isEmployeeMode){
    // Les vraies données arrivent via attachRealtimeListener (temps réel, compte du
    // patron). En attendant cette réponse (qui prend un instant après un rafraîchissement),
    // on restaure la dernière copie locale connue pour ne pas afficher des chiffres à
    // zéro pendant la reconnexion — pushToCloud() reste bloqué par employeeSyncReady
    // tant que la vraie synchro n'a pas eu lieu, donc cette copie locale ne peut jamais
    // écraser les données du patron.
    try{
      const p = localGet('mombongo:products'); products = p ? JSON.parse(p.value) : [];
      const s = localGet('mombongo:sales'); sales = s ? JSON.parse(s.value) : [];
      const l = localGet('mombongo:lots'); lots = l ? JSON.parse(l.value) : [];
      lots.forEach(lot=>recalcLotQuantities(lot.id));
      const d = localGet('mombongo:debts'); debts = d ? JSON.parse(d.value) : [];
      const ex = localGet('mombongo:expenses'); expenses = ex ? JSON.parse(ex.value) : [];
      const al = localGet('mombongo:activityLog'); activityLog = al ? JSON.parse(al.value) : [];
      const st = localGet('mombongo:stats');
      stats = st ? JSON.parse(st.value) : { todayDate: '', todaySales: 0, todayProfit: 0, totalProfit: 0, totalExpenses: 0 };
      if(typeof stats.totalExpenses !== 'number') stats.totalExpenses = 0;
    }catch(e){
      products = []; sales = []; lots = []; debts = []; expenses = []; activityLog = [];
      stats = { todayDate: '', todaySales: 0, todayProfit: 0, totalProfit: 0, totalExpenses: 0 };
    }
    render();
    return;
  }
  try{
    const p = localGet('mombongo:products');
    products = p ? JSON.parse(p.value) : [];
  }catch(e){ products = []; }
  try{
    const s = localGet('mombongo:sales');
    sales = s ? JSON.parse(s.value) : [];
  }catch(e){ sales = []; }
  try{
    const l = localGet('mombongo:lots');
    lots = l ? JSON.parse(l.value) : [];
  }catch(e){ lots = []; }
  lots.forEach(lot=>recalcLotQuantities(lot.id));
  try{
    const d = localGet('mombongo:debts');
    debts = d ? JSON.parse(d.value) : [];
  }catch(e){ debts = []; }
  try{
    const ex = localGet('mombongo:expenses');
    expenses = ex ? JSON.parse(ex.value) : [];
  }catch(e){ expenses = []; }
  try{
    const st = localGet('mombongo:stats');
    stats = st ? JSON.parse(st.value) : { todayDate: '', todaySales: 0, todayProfit: 0, totalProfit: 0, totalExpenses: 0 };
    if(typeof stats.totalExpenses !== 'number') stats.totalExpenses = 0;
  }catch(e){ stats = { todayDate: '', todaySales: 0, todayProfit: 0, totalProfit: 0, totalExpenses: 0 }; }
  try{
    const r = localGet('mombongo:rate');
    if(r){ const parsedRate = parseFloat(r.value); if(parsedRate > 0) exchangeRate = parsedRate; document.getElementById('in-rate').value = exchangeRate; }
  }catch(e){}
  try{
    const c = localGet('mombongo:currency');
    if(c && c.value === 'cdf'){ setCurrency('cdf'); }
  }catch(e){}
  await archiveOldData();
  render();
}

