function getCatalogForStore(storeId){
  const store = stores.find(s=>s.id===storeId);
  if(!store) return null;
  if(store.type === 'pharmacie') return PHARMA_PRODUCTS;
  if(store.type === 'quincaillerie') return QUINCAILLERIE_PRODUCTS;
  if(store.type === 'boutique') return BOUTIQUE_PRODUCTS;
  return null; // autre : pas encore de catalogue partagé (mais garde ses suggestions personnelles)
}

let activeCatalogForForm = null;
const CATALOG_FIELD_IDS = ['in-name', 'carton-name', 'sac-name'];

function getFullCatalogForActiveStore(){
  const shared = getCatalogForStore(activeStoreId) || [];
  // Voir community-catalog.js : produits ajoutés par SCAN par n'importe quel utilisateur
  // Mombongo du même type de commerce — se comporte comme une extension vivante du
  // catalogue statique ci-dessus, sans action supplémentaire de la part de l'utilisateur.
  const community = (typeof getCommunityCatalogNames === 'function') ? getCommunityCatalogNames() : [];
  const seen = new Set();
  const merged = [];
  [...customCatalog, ...community, ...shared].forEach(n=>{
    const key = n.toLowerCase();
    if(!seen.has(key)){ seen.add(key); merged.push(n); }
  });
  return merged;
}

function updateProductNameSuggestions(){
  const merged = getFullCatalogForActiveStore();
  activeCatalogForForm = merged.length ? merged : null;
  CATALOG_FIELD_IDS.forEach(fieldId=>{
    const arrowBtn = document.getElementById('catalog-arrow-'+fieldId);
    if(arrowBtn) arrowBtn.style.display = activeCatalogForForm ? 'flex' : 'none';
    closeCatalogPanel(fieldId);
  });
  // Le bouton "Ajout rapide depuis le catalogue" n'a de sens que pour un NOUVEAU produit
  // (pas en modification d'un produit existant — add-mode-row sert justement de repère
  // pour ça, il est déjà caché par openEditSheet()) et seulement s'il existe un catalogue.
  const bulkBtn = document.getElementById('t-bulk-catalog-open-btn');
  const addModeRow = document.getElementById('add-mode-row');
  const isNewProductMode = addModeRow && addModeRow.style.display !== 'none';
  if(bulkBtn){
    bulkBtn.style.display = (activeCatalogForForm && isNewProductMode) ? 'block' : 'none';
  }
  // La saisie rapide en tableau ne dépend elle d'aucun catalogue (c'est de la saisie
  // manuelle) — uniquement du mode "nouveau produit".
  const gridBtn = document.getElementById('t-grid-add-open-btn');
  if(gridBtn) gridBtn.style.display = isNewProductMode ? 'block' : 'none';
}

function maybeOfferCustomCatalogSave(name){
  if(!name) return;
  const merged = getFullCatalogForActiveStore();
  const alreadyKnown = merged.some(n => n.toLowerCase() === name.toLowerCase());
  if(alreadyKnown) return;
  const msg = currentLang==='fr'
    ? `Ajouter "${name}" à tes suggestions, pour ne plus le retaper en entier la prochaine fois ?`
    : currentLang==='ln'
      ? `Kobakisa "${name}" na ba suggestions na yo, mpo kozongela kokoma yango mobimba lisusu te ?`
      : `Ongeza "${name}" kwenye mapendekezo yako, ili usirudie kuandika jina lote tena ?`;
  if(window.confirm(msg)){
    customCatalog.push(name);
    saveProducts();
  }
}

function filterCatalog(query){
  if(!activeCatalogForForm) return [];
  const q = query.trim().toLowerCase();
  if(!q) return activeCatalogForForm; // navigation libre : liste complète, pas de plafond
  return activeCatalogForForm.filter(n => n.toLowerCase().includes(q)).slice(0, 150);
}


function toggleCatalogPanel(fieldId){
  const panel = document.getElementById('catalog-panel-'+fieldId);
  if(!panel || !activeCatalogForForm) return;
  if(panel.style.display === 'block'){ closeCatalogPanel(fieldId); return; }
  renderCatalogPanel(fieldId, filterCatalog(''));
}

function closeCatalogPanel(fieldId){
  const panel = document.getElementById('catalog-panel-'+fieldId);
  if(panel) panel.style.display = 'none';
}

function onCatalogFieldInput(fieldId){
  if(!activeCatalogForForm) return;
  const val = document.getElementById(fieldId).value;
  if(!val.trim()){ closeCatalogPanel(fieldId); return; }
  renderCatalogPanel(fieldId, filterCatalog(val));
}

function pickCatalogItem(fieldId, name){
  document.getElementById(fieldId).value = name;
  closeCatalogPanel(fieldId);
}

